import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Main Page","description":"","frontmatter":{"title":"Main Page"},"headers":[],"relativePath":"ai-ml/main-page.md","filePath":"ai-ml/main-page.md","lastUpdated":null}'),o={name:"ai-ml/main-page.md"};function n(s,e,l,h,c,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="main-page" tabindex="-1">Main Page <a class="header-anchor" href="#main-page" aria-label="Permalink to &quot;Main Page&quot;">​</a></h1><h2 id="welcome-to-irregular-chat-🚀" tabindex="-1">Welcome to Irregular Chat 🚀 <a class="header-anchor" href="#welcome-to-irregular-chat-🚀" aria-label="Permalink to &quot;Welcome to Irregular Chat 🚀&quot;">​</a></h2><p>Welcome to the IrregularChat Community of Interest (COI), where diverse minds—tech enthusiasts, researchers, and innovators converge. The <strong>Irregular Chat</strong> CoI is a dynamic space to discuss the latest in technology, share knowledge, and collaborate on groundbreaking projects.</p><p>Embrace a spirit of professional impatience and be ready to break down silos!</p><ol><li>📜 Rules of Engagement For the full list and community FAQ see the <a href="https://forum.irregularchat.com/t/irregularchat-community-faq-guidelines/4" target="_blank" rel="noreferrer">IrregularChat Forum</a>.</li></ol><h2 id="leave-your-rank-and-ego-at-the-door" tabindex="-1">Leave your rank and ego at the door. <a class="header-anchor" href="#leave-your-rank-and-ego-at-the-door" aria-label="Permalink to &quot;Leave your rank and ego at the door.&quot;">​</a></h2><h2 id="stay-on-topic-to-maintain-focus-mark-jokes-and-sarcasm-with-j-or-s-do-not-joke-about-leaking-or-spilling-classified-information-others-will-report-this-action-to-their-s-g-j2" tabindex="-1">Stay on topic to maintain focus. Mark jokes and sarcasm with <code>/j</code> or <code>/s</code>. Do NOT joke about leaking or spilling classified information. Others will report this action to their S/G/J2. <a class="header-anchor" href="#stay-on-topic-to-maintain-focus-mark-jokes-and-sarcasm-with-j-or-s-do-not-joke-about-leaking-or-spilling-classified-information-others-will-report-this-action-to-their-s-g-j2" aria-label="Permalink to &quot;Stay on topic to maintain focus. Mark jokes and sarcasm with `/j` or `/s`. Do NOT joke about leaking or spilling classified information. Others will report this action to their S/G/J2.&quot;">​</a></h2><h2 id="avoid-sharing-confidential-personally-identifiable-information-pii-or-classified-information-encryption-does-not-make-it-permissible" tabindex="-1">Avoid sharing confidential, personally identifiable information (PII) or classified information. Encryption does not make it permissible. <a class="header-anchor" href="#avoid-sharing-confidential-personally-identifiable-information-pii-or-classified-information-encryption-does-not-make-it-permissible" aria-label="Permalink to &quot;Avoid sharing confidential, personally identifiable information (PII) or classified information. Encryption does not make it permissible.&quot;">​</a></h2><h3 id="navigate-content-using-the-appropriate-levels-and-direct-users-to-relevant-content-locations" tabindex="-1">Navigate content using the appropriate levels and direct users to relevant content locations. <a class="header-anchor" href="#navigate-content-using-the-appropriate-levels-and-direct-users-to-relevant-content-locations" aria-label="Permalink to &quot;Navigate content using the appropriate levels and direct users to relevant content locations.&quot;">​</a></h3><h2 id="chatham-house-rule-used-throughout-unless-stated-otherwise-participants-can-use-information-shared-but-must-not-reveal-the-source-or-identity-of-the-speaker-outside-of-the-irregularchat-community" tabindex="-1">Chatham House Rule used throughout, unless stated otherwise. Participants can use information shared but must not reveal the source or identity of the speaker outside of the IrregularChat Community. <a class="header-anchor" href="#chatham-house-rule-used-throughout-unless-stated-otherwise-participants-can-use-information-shared-but-must-not-reveal-the-source-or-identity-of-the-speaker-outside-of-the-irregularchat-community" aria-label="Permalink to &quot;Chatham House Rule used throughout, unless stated otherwise. Participants can use information shared but must not reveal the source or identity of the speaker outside of the IrregularChat Community.&quot;">​</a></h2><h2 id="don-t-be-disrespectful-to-members" tabindex="-1">Don’t be disrespectful to members. <a class="header-anchor" href="#don-t-be-disrespectful-to-members" aria-label="Permalink to &quot;Don’t be disrespectful to members.&quot;">​</a></h2><h2 id="engage-with-the-wiki-and-forum" tabindex="-1">Engage with the Wiki and Forum: <a class="header-anchor" href="#engage-with-the-wiki-and-forum" aria-label="Permalink to &quot;Engage with the Wiki and Forum:&quot;">​</a></h2><h3 id="utilize-the-wiki-for-resources-if-you-find-gaps-fill-them-in-and-share-them-in-the-chat" tabindex="-1">Utilize the wiki for resources. If you find gaps, fill them in and share them in the chat. <a class="header-anchor" href="#utilize-the-wiki-for-resources-if-you-find-gaps-fill-them-in-and-share-them-in-the-chat" aria-label="Permalink to &quot;Utilize the wiki for resources. If you find gaps, fill them in and share them in the chat.&quot;">​</a></h3><h3 id="notice-inaccuracies-or-missing-information-lead-the-effort-to-correct-and-enhance-it" tabindex="-1">Notice inaccuracies or missing information? Lead the effort to correct and enhance it. <a class="header-anchor" href="#notice-inaccuracies-or-missing-information-lead-the-effort-to-correct-and-enhance-it" aria-label="Permalink to &quot;Notice inaccuracies or missing information? Lead the effort to correct and enhance it.&quot;">​</a></h3><h3 id="if-you-encounter-a-missing-page-take-the-initiative-to-create-it" tabindex="-1">If you encounter a missing page, take the initiative to create it. <a class="header-anchor" href="#if-you-encounter-a-missing-page-take-the-initiative-to-create-it" aria-label="Permalink to &quot;If you encounter a missing page, take the initiative to create it.&quot;">​</a></h3><ol><li>🌟 Getting Started <strong>Secure Your Spot</strong>: Ensure you’re part of the community by getting added to the <a href="/community/join.html">Chat Login</a>.</li></ol><p><strong>Engage</strong>: Participate in discussions, see announcements, and access resources - <a href="https://github.com/orgs/irregularchat/discussions" target="_blank" rel="noreferrer">Irregular Chat Discussions</a>.</p><p><strong>Access Exclusive Content</strong>: Use your login for services and to access <a href="/general/links.html">wiki pages</a>.</p><p>📖 <strong>Tip</strong>: Our wiki is vast and continually evolving. Use the navigation on the left, the search bar, or the links below to explore topics of interest. Logged-in users can edit and create new pages, contributing to our collective knowledge.</p><ol><li>🚀 Wiki Quick Links</li></ol><h3 id="📘-key-resources" tabindex="-1">📘 Key Resources <a class="header-anchor" href="#📘-key-resources" aria-label="Permalink to &quot;📘 Key Resources&quot;">​</a></h3><ul><li><p><a href="/general/learning.html">Resources</a>, including <a href="/general/certifications.html">Resources</a></p></li><li><p><a href="/research/">Resources</a> with detailed <a href="/research/research-datasets.html">Research Resources</a></p></li><li><p><a href="/ai-ml/ai-resources.html"> AI/ML Resources</a></p></li><li><p><a href="/general/business.html">Business Tools</a></p></li><li><p><a href="/general/learning.html">Reading Lists</a></p></li></ul><h3 id="👽-community-hub" tabindex="-1">👽 Community Hub <a class="header-anchor" href="#👽-community-hub" aria-label="Permalink to &quot;👽 Community Hub&quot;">​</a></h3><p>The community section requires login; it houses chat archives and more:</p><ul><li><p><a href="https://forum.irregularchat.com/c/general/4" target="_blank" rel="noreferrer">Technology Discussions</a></p></li><li><p><a href="/general/business.html">Strategies and Insights</a></p></li><li><p><a href="/general/unmanned-systems.html">Topics in Unmanned Systems</a></p></li><li><p><a href="/general/unsorted.html">Contributions</a> from chats that need organization.</p></li><li><p><a href="/server-guides/">Guides</a></p></li></ul><h4 id="special-interest-discussions" tabindex="-1">Special Interest Discussions <a class="header-anchor" href="#special-interest-discussions" aria-label="Permalink to &quot;Special Interest Discussions&quot;">​</a></h4><ul><li><p><a href="https://forum.irregularchat.com/tag/tech" target="_blank" rel="noreferrer">Tech Discussions</a></p></li><li><p><a href="https://forum.irregularchat.com/tag/ai" target="_blank" rel="noreferrer">AI/ML Discussions</a></p></li><li><p><a href="https://forum.irregularchat.com/tag/business" target="_blank" rel="noreferrer">Business Discussions</a></p></li></ul><h3 id="📚-focus-areas" tabindex="-1">📚 Focus Areas <a class="header-anchor" href="#📚-focus-areas" aria-label="Permalink to &quot;📚 Focus Areas&quot;">​</a></h3><p>Explore our core topics:</p><ul><li><p>[* <a href="/research/">Tech Wiki Pages</a></p><ul><li><a href="/cybersecurity/">Essentials</a></li><li><a href="/general/dfp-guide.html">Guides</a></li></ul></li><li><p><a href="https://forum.irregularchat.com/tag/influence" target="_blank" rel="noreferrer">Influence</a></p></li></ul><ol><li>🗂 Sharing Content Ensure your shared content adds value:</li></ol><h2 id="search-the-wiki-before-posting-which-is-made-from-content-shared-in-the-chats" tabindex="-1">Search the wiki before posting, which is made from content shared in the chats. <a class="header-anchor" href="#search-the-wiki-before-posting-which-is-made-from-content-shared-in-the-chats" aria-label="Permalink to &quot;Search the wiki before posting, which is made from content shared in the chats.&quot;">​</a></h2><h2 id="search-the-forum-irregularchat-forum-if-the-article-isn-t-there-add-it-and-reference-it-on-the-chat" tabindex="-1">Search the Forum <a href="https://forum.irregularchat.com" target="_blank" rel="noreferrer">IrregularChat Forum</a>. If the article isn’t there, add it and reference it on the chat. <a class="header-anchor" href="#search-the-forum-irregularchat-forum-if-the-article-isn-t-there-add-it-and-reference-it-on-the-chat" aria-label="Permalink to &quot;Search the Forum [IrregularChat Forum](https://forum.irregularchat.com). If the article isn’t there, add it and reference it on the chat.&quot;">​</a></h2><h3 id="context-is-key" tabindex="-1">Context is Key <a class="header-anchor" href="#context-is-key" aria-label="Permalink to &quot;Context is Key&quot;">​</a></h3><ul><li><p>Share context, not just links.</p></li><li><p>Use #tagged categories.</p></li><li><p>Scan for malware with <a href="https://www.virustotal.com/gui/home/upload" target="_blank" rel="noreferrer">VirusTotal</a>.</p></li></ul><h3 id="📺-links-and-documents" tabindex="-1">📺 Links and Documents <a class="header-anchor" href="#📺-links-and-documents" aria-label="Permalink to &quot;📺 Links and Documents&quot;">​</a></h3><ul><li><p>For videos, convert them to MP4 with <code>ffmpeg</code> or <a href="https://cloudconvert.com/mov-to-mp4" target="_blank" rel="noreferrer">CloudConvert Web</a>.</p></li><li><p>Bypass paywalls with platforms like:</p><ul><li><a href="https://paywallhub.com/" target="_blank" rel="noreferrer">PaywallHub</a></li><li><a href="https://12ft.io/" target="_blank" rel="noreferrer">12ft.io</a></li><li><a href="https://archive.is/" target="_blank" rel="noreferrer">Archive.is</a></li><li><a href="https://archive.ph/" target="_blank" rel="noreferrer">Archive.ph</a></li><li><a href="https://www.printfriendly.com/" target="_blank" rel="noreferrer">PrintFriendly</a></li><li>On iOS or Mac: <a href="https://www.icloud.com/shortcuts/81c670b532e340e38a35cc62e3e9397d" target="_blank" rel="noreferrer">iCloud Shortcut</a></li></ul></li><li><p>Find archived versions:</p><ul><li><a href="https://archive.org/" target="_blank" rel="noreferrer">Internet Archive</a></li></ul></li></ul><p><strong>(Test with multiple browsers if the paywall is not off)</strong></p><h3 id="🌐-proxy-frontend-links" tabindex="-1">🌐 Proxy Frontend Links <a class="header-anchor" href="#🌐-proxy-frontend-links" aria-label="Permalink to &quot;🌐 Proxy Frontend Links&quot;">​</a></h3><p>Share content through proxies like:</p><ul><li><p>TikTok Links: <a href="https://github.com/pablouser1/ProxiTok/wiki/Public-instances#clearnet" target="_blank" rel="noreferrer">Frontend Proxy</a></p></li><li><p>YouTube: <a href="https://docs.invidious.io/instances/" target="_blank" rel="noreferrer">Frontend Proxy</a></p></li></ul><h3 id="summary-generation" tabindex="-1">Summary Generation <a class="header-anchor" href="#summary-generation" aria-label="Permalink to &quot;Summary Generation&quot;">​</a></h3><ul><li><p><a href="https://smmry.com/" target="_blank" rel="noreferrer">SMMRY</a></p></li><li><p><a href="https://quillbot.com/summarize/" target="_blank" rel="noreferrer">QuillBot AI Summarizer</a></p></li><li><p><a href="/ai-ml/">AI Resources</a></p></li></ul><p><em><strong>Consuming Content While Exploring Shared Links or Documents:</strong></em></p><ul><li><p>Trust cautiously. Always double-check URLs.</p></li><li><p>Spot a vulnerability?</p><ul><li>Report or Question it immediately with context.</li></ul></li><li><p>Use a virtual environment like <a href="https://vm.irregularchat.com/" target="_blank" rel="noreferrer">Kasm</a> and scan files with <a href="https://www.virustotal.com/gui/home/upload" target="_blank" rel="noreferrer">VirusTotal</a>.</p></li></ul><hr><h3 id="semi-automated-bot-content" tabindex="-1">Semi-Automated Bot Content <a class="header-anchor" href="#semi-automated-bot-content" aria-label="Permalink to &quot;Semi-Automated Bot Content&quot;">​</a></h3><ul><li>A place for bots to append stuff when commanded (not automatically) for a human to organize later somewhere on the wiki (currently just testing).</li></ul><p>[Community]</p>',49)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
